```jsx
import { TimePicker } from '@wordpress/components';
import { useState } from '@wordpress/element';

const MyTimeInput = () => {
	const [ time, setTime ] = useState( { hours: 13, minutes: 30 } );

	return (
		<TimePicker.TimeInput
			value={ time }
			onChange={ setTime }
			label="Time"
		/>
	);
};
```

