const MenuTrigger = () => {
    const [ menuOpen, setMenuOpen ] = useState( false );
    return (
        <>
            <Menu.Root onOpenChange={ setMenuOpen } open={ menuOpen }>
                <Menu.Trigger>Actions ▾</Menu.Trigger>
                <Menu.Portal>
                    <Menu.Positioner>
                        <Menu.Popup style={ menuPopupStyles }>
                            <Menu.Item style={ menuItemStyles }>
                                Edit
                            </Menu.Item>
                            <AlertDialog.Root
                                onConfirm={ () => {
                                    setMenuOpen( false );
