const AsyncConfirm = () => {
    const [ shouldFail, setShouldFail ] = useState( false );
    const successId = useId();
    const failureId = useId();

    return (
        <>
            <fieldset>
                <legend>Async task outcome</legend>
                <label htmlFor={ successId }>
                    <input
                        id={ successId }
                        type="radio"
                        name="async-outcome"
                        checked={ ! shouldFail }
                        onChange={ () => setShouldFail( false ) } />Success (closes dialog)
                                        </label>
                <label htmlFor={ failureId } style={ { marginInlineStart: 12 } }>
                    <input
                        id={ failureId }
                        type="radio"
                        name="async-outcome"
                        checked={ shouldFail }
                        onChange={ () => setShouldFail( true ) } />Failure (dialog stays open, shows error)
                                        </label>
            </fieldset>
            <br />
            <AlertDialog.Root
                onConfirm={ async () => {
                    action( 'onConfirm' )();
                    try {
                        await sleep( 2000 );
                        if ( shouldFail ) {
                            throw new Error( 'Task failed' );
                        }
                    } catch {
                        return {
                            close: false,
                            error: 'Something went wrong. Please try again.',
                        };
                    }
                    return undefined;
                } }>
                <AlertDialog.Trigger>Delete permanently
                                        </AlertDialog.Trigger>
                <AlertDialog.Popup
                    intent="irreversible"
                    title="Delete permanently?"
                    description="This action cannot be undone. All data will be lost."
                    confirmButtonText="Delete permanently" />
            </AlertDialog.Root>
        </>
    );
};

