const Controlled = () => {
    const [ isOpen, setIsOpen ] = useState( false );
    const checkboxId = useId();
    const checkboxRef = useRef< HTMLInputElement >( null );
    const labelRef = useRef< HTMLLabelElement >( null );

    return (
        <div
            style={ {
                display: 'flex',
                gap: '1rem',
                alignItems: 'center',
            } }>
            <Popover.Root
                open={ isOpen }
                onOpenChange={ ( nextOpen, eventDetails ) => {
                    if (
                        [ 'outside-press', 'focus-out' ].includes(
                            eventDetails.reason
                        ) &&
                        !! eventDetails.event.target &&
                        (
                            [
                                checkboxRef.current,
                                labelRef.current,
                            ].filter( Boolean ) as EventTarget[]
                         ).includes( eventDetails.event.target )
                    ) {
                        return;
                    }

                    setIsOpen( nextOpen );
                } }><>
                    <Popover.Trigger>Toggle Popover</Popover.Trigger>
                    <Popover.Popup>
                        <Popover.Arrow />
                        <Popover.Title
                            style={ {
                                marginBottom: 'var(--wpds-dimension-gap-xs)',
                            } }>Controlled Popover
                                                </Popover.Title>
                        <Popover.Description>This popover is controlled by external state.
                                                </Popover.Description>
                    </Popover.Popup>
                </></Popover.Root>
            <label htmlFor={ checkboxId } ref={ labelRef }>
                <input
                    ref={ checkboxRef }
                    id={ checkboxId }
                    type="checkbox"
                    checked={ isOpen }
                    onChange={ ( e ) => setIsOpen( e.target.checked ) } />Open
                                </label>
        </div>
    );
};

const OverlayPlacement = () => {
    const [ popupRef, popupSize ] = useMeasure< HTMLDivElement >();
    const [ triggerRef, triggerSize ] = useMeasure< HTMLButtonElement >();

    return (
        <div style={ { padding: '4rem', textAlign: 'center' } }>
            <Popover.Root defaultOpen>
                <Popover.Trigger ref={ triggerRef }>Trigger (covered by popover)
                                        </Popover.Trigger>
                <Popover.Popup
                    ref={ popupRef }
                    side="bottom"
                    align="center"
                    sideOffset={
                        -1 *
                        ( popupSize.height / 2 + triggerSize.height / 2 )
                    }
                    collisionAvoidance={ {
                        side: 'none',
                        align: 'none',
                    } }>
                    <Popover.Title
                        style={ {
                            marginBottom: 'var(--wpds-dimension-gap-xs)',
                        } }>Overlay
                                                </Popover.Title>
                    <Popover.Description>This popover is centered over its trigger using a
                                                    negative sideOffset.
                                                    <br />The trigger is currently hidden under the popover.
                                                    <br />Try resizing the browser — collision avoidance is
                                                    disabled so the popover stays overlaid.
                                                </Popover.Description>
                </Popover.Popup>
            </Popover.Root>
        </div>
    );
};

const Inline = function Render() {
    const inlineContainerRef = useRef< HTMLSpanElement >( null );

    return (
        <div data-testid="inline-wrapper">
            <Popover.Root>
                <Popover.Trigger>Open Inline</Popover.Trigger>
                <span
                    ref={ inlineContainerRef }
                    style={ { display: 'contents' } }
                />
                <Popover.Popup container={ inlineContainerRef }>
                    <Popover.Arrow />
