const Anchor = function Render() {
    const [ elementAnchor, setElementAnchor ] =
        useState< HTMLElement | null >( null );
    const refAnchor = useRef< HTMLDivElement >( null );
    const virtualAnchorLabel = useRef< HTMLDivElement >( null );
    const callbackTarget = useRef< HTMLDivElement >( null );

    const virtualAnchor = {
        getBoundingClientRect: () =>
            virtualAnchorLabel.current?.getBoundingClientRect() ??
            new DOMRect(),
    };

    const anchorBoxStyle = {
        padding: '8px 12px',
        border: '2px dashed currentcolor',
        borderRadius: 4,
        fontSize: 12,
        textAlign: 'center' as const,
    };

    const popupProps = {
        collisionAvoidance: {
            side: 'none' as const,
            align: 'none' as const,
        },
    };

    return (
        <div
            style={ {
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: '4rem',
                padding: '4rem 2rem',
            } }
        >
            { /* 1. Element anchor */ }
            <div>
                <div ref={ setElementAnchor } style={ anchorBoxStyle }>
                    Element anchor
                </div>
                <Popover.Root open>
                    <Popover.Popup
                        anchor={ elementAnchor ?? undefined }
                        { ...popupProps }
                    >
                        <VisuallyHidden render={ <Popover.Title /> }>
                            Element anchor
                        </VisuallyHidden>
                        <Popover.Arrow />
                        <Popover.Description>
                            Anchored to a DOM element
                        </Popover.Description>
                    </Popover.Popup>
                </Popover.Root>
            </div>

            { /* 2. VirtualElement anchor */ }
            <div>
                <div ref={ virtualAnchorLabel } style={ anchorBoxStyle }>
                    VirtualElement anchor
                </div>
                <Popover.Root open>
                    <Popover.Popup
                        anchor={ virtualAnchor }
                        { ...popupProps }
                    >
                        <VisuallyHidden render={ <Popover.Title /> }>
                            Virtual anchor
                        </VisuallyHidden>
                        <Popover.Arrow />
                        <Popover.Description>
                            Anchored to a virtual element
                        </Popover.Description>
                    </Popover.Popup>
                </Popover.Root>
            </div>

            { /* 3. RefObject anchor */ }
            <div>
                <div ref={ refAnchor } style={ anchorBoxStyle }>
                    RefObject anchor
                </div>
                <Popover.Root open>
                    <Popover.Popup anchor={ refAnchor } { ...popupProps }>
                        <VisuallyHidden render={ <Popover.Title /> }>
                            Ref anchor
                        </VisuallyHidden>
                        <Popover.Arrow />
                        <Popover.Description>
                            Anchored via useRef
                        </Popover.Description>
                    </Popover.Popup>
                </Popover.Root>
            </div>

            { /* 4. Callback anchor */ }
            <div>
                <div ref={ callbackTarget } style={ anchorBoxStyle }>
                    Callback anchor
                </div>
                <Popover.Root open>
                    <Popover.Popup
                        anchor={ () => callbackTarget.current }
                        { ...popupProps }
                    >
                        <VisuallyHidden render={ <Popover.Title /> }>
                            Callback anchor
                        </VisuallyHidden>
                        <Popover.Arrow />
                        <Popover.Description>
                            Anchored via callback function
                        </Popover.Description>
                    </Popover.Popup>
                </Popover.Root>
            </div>
        </div>
    );
};

